public static bool ShouldProcess(DateTimeOffset lastWrite, DateTimeOffset now, TimeSpan protection)
{
    return lastWrite <= now - protection;
}

public async Task SaveAsync(string path, string text, CancellationToken token)
{
    await writer.WriteAsync(path, text, token);
}

public WorkItem? TakeNext(IEnumerable<WorkItem> items)
{
    return items.OrderByDescending(x => x.Priority)
        .ThenByDescending(x => x.LastWriteUtc).FirstOrDefault();
}
